import * as tt from "thinkthen";

// the outage first at 0.94, the quote second at 0.93
const inbox = ["Newsletter: our autumn catalog is here",
    "Our checkout page is down and customers cannot pay",
    "The client needs the signed quote by 5 pm today.",
    "Reminder: your invoice is due in 30 days"];
const ranked = await tt.rank("Does this need an answer today?",
    inbox, { top: 2 });
for (const one of ranked) console.log(one.probability, one.record);
